// Lista de produtos
let produtos = [];


// Função para mostrar mensagens
function mostrarMensagem(texto, tipo) {

    const mensagem = document.getElementById("mensagem");

        mensagem.textContent = texto;
            mensagem.className = "mensagem " + tipo;

            }


            // Função para validar produto
            function validarProduto(descricao, quantidade, valor) {

                if (descricao.trim().length < 5) {
                        throw new Error(
                                    "A descrição deve ter, no mínimo, cinco caracteres."
                                            );
                                                }

                                                    if (!Number.isFinite(quantidade) || quantidade < 1) {
                                                            throw new Error(
                                                                        "A quantidade deve ser maior que zero."
                                                                                );
                                                                                    }

                                                                                        if (!Number.isFinite(valor) || valor < 0) {
                                                                                                throw new Error(
                                                                                                            "O valor deve ser maior ou igual a zero."
                                                                                                                    );
                                                                                                                        }

                                                                                                                        }


                                                                                                                        // Função para cadastrar produto
                                                                                                                        function cadastrarProduto(descricao, quantidade, valor) {

                                                                                                                            validarProduto(descricao, quantidade, valor);

                                                                                                                                let novoProduto = {

                                                                                                                                        codigo: produtos.length + 1,

                                                                                                                                                descricao: descricao.trim(),

                                                                                                                                                        quantidade: quantidade,

                                                                                                                                                                valor: valor

                                                                                                                                                                    };

                                                                                                                                                                        produtos.push(novoProduto);

                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                mostrarMensagem(
                                                                                                                                                                                        "Produto cadastrado com sucesso!",
                                                                                                                                                                                                "sucesso"
                                                                                                                                                                                                    );

                                                                                                                                                                                                    }


                                                                                                                                                                                                    // Função para listar produtos
                                                                                                                                                                                                    function listarProdutos() {

                                                                                                                                                                                                        const lista = document.getElementById("listaProdutos");

                                                                                                                                                                                                            lista.innerHTML = "";

                                                                                                                                                                                                                produtos.forEach((produto) => {

                                                                                                                                                                                                                        let linha = document.createElement("tr");

                                                                                                                                                                                                                                linha.innerHTML = `
                                                                                                                                                                                                                                            <td>${produto.codigo}</td>

                                                                                                                                                                                                                                                        <td></td>

                                                                                                                                                                                                                                                                    <td>${produto.quantidade}</td>

                                                                                                                                                                                                                                                                                <td>${formatarMoeda(produto.valor)}</td>

                                                                                                                                                                                                                                                                                            <td>${formatarMoeda(
                                                                                                                                                                                                                                                                                                            produto.quantidade * produto.valor
                                                                                                                                                                                                                                                                                                                        )}</td>
                                                                                                                                                                                                                                                                                                                                `;

                                                                                                                                                                                                                                                                                                                                        // Insere a descrição como texto
                                                                                                                                                                                                                                                                                                                                                linha.children[1].textContent = produto.descricao;

                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                if (produtos.length === 0) {

                                                                                                                                                                                                                                                                                                                                                                        lista.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                    <tr>
                                                                                                                                                                                                                                                                                                                                                                                                    <td colspan="5">
                                                                                                                                                                                                                                                                                                                                                                                                                        Nenhum produto cadastrado.
                                                                                                                                                                                                                                                                                                                                                                                                                                        </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarResumo();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Formatar valores em reais
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function formatarMoeda(valor) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Atualizar informações do estoque
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarResumo() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const totalProdutos = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const totalUnidades = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (total, produto) => total + produto.quantidade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("totalProdutos").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    totalProdutos;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("totalUnidades").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                totalUnidades;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Buscar produto pelo código
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function buscarProdutoPorCodigo(codigoProduto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return produtos.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (prod) => prod.codigo === codigoProduto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Função para atualizar valor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function atualizarValor(codigoProduto, novoValor) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!Number.isFinite(novoValor) || novoValor < 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "O valor deve ser maior ou igual a zero."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const produto = buscarProdutoPorCodigo(codigoProduto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (produto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Valor atualizado com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                throw new Error("Produto não encontrado.");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Função para atualizar quantidade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarQuantidade(codigoProduto, novaQuantidade) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!Number.isFinite(novaQuantidade) || novaQuantidade < 1) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "A quantidade deve ser maior que zero."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const produto = buscarProdutoPorCodigo(codigoProduto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (produto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produto.quantidade =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.quantidade + novaQuantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Estoque atualizado com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                throw new Error("Produto não encontrado.");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Evento de cadastro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("formCadastro")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const descricao =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("descricao").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const quantidade =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Number(document.getElementById("quantidade").value);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const valor =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number(document.getElementById("valor").value);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cadastrarProduto(descricao, quantidade, valor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(erro.message, "erro");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Evento de atualização do valor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("formValor")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("codigoValor").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const novoValor = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("novoValor").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarValor(codigo, novoValor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(erro.message, "erro");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Evento de atualização da quantidade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("formQuantidade")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("codigoQuantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const novaQuantidade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("novaQuantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarQuantidade(codigo, novaQuantidade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(erro.message, "erro");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Inicializar sistema
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();